// 图标描边阶梯：16px 用 1.75（保持视觉重量），其余用 2（设计规范 DESIGN.md §4）。
export function iconMarkup(name, size = 20) {
  const body = BODY[name];
  if (!body) return '';
  const sw = size <= 16 ? 1.75 : 2;
  return `<svg class="ic" xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}"`
    + ` viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="${sw}"`
    + ` stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${body}</svg>`;
}

export const ICON_NAMES = Object.keys(BODY);
export function hasIcon(name) { return Object.prototype.hasOwnProperty.call(BODY, name); }
